<div class="card table-responsive"><table class="table"><thead><tr><?php foreach([__t('Time','زمان','وخت'),__t('Person','شخص','شخص'),__t('Branch','شعبه','څانګه'),__t('Event','رویداد','پېښه'),__t('Record','سند','سند'),__t('Changes','تغییرات','بدلونونه')] as $h):?><th><?= sanitize($h) ?></th><?php endforeach ?></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?= sanitize(ui_date($r['created_at'].' UTC')) ?></td><td><?= sanitize($r['fullname']??'System') ?></td><td><?= sanitize($r['branch_name']??'Central') ?></td><td><?= sanitize($r['event_type']) ?></td><td><?= sanitize($r['entity_type'].' #'.$r['entity_id']) ?></td><td><details><summary><?= __t('Details','جزئیات','جزیات') ?></summary><pre><?= sanitize(json_for_html(['before'=>json_decode($r['before_json']??'null',true),'after'=>json_decode($r['after_json']??'null',true)],JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE)) ?></pre></details></td></tr><?php endforeach ?></tbody></table></div>
